# Merge/zero-length epsilon. Matches editor_server._MERGE_EPS so the kept-segment
# math agrees with the removed-range math the rest of the app uses.
_EPS = 0.001

# Video containers we'll consider when mapping a proxy stem back to its original.
_VIDEO_SUFFIXES = (".mp4", ".MP4", ".mov", ".MOV", ".m4v", ".mkv", ".webm")

# Resolution policy. Export at the source height, capped here. 1440p (2560x1440)
# and below pass through untouched; only a source TALLER than this is downscaled,
# and only down to this cap — so a 1080p master stays 1080p and a 4K master
# becomes ~1440p instead of a needlessly huge 2160p file.
